sql.where:
p.status <> 'HIDDEN'



		AND p.barcode = #{barcode}


		AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR a.name LIKE CONCAT('%', #{keyword}, '%')

			OR p.catalog_no_normalized = #{catalogNoNormalized}

		)



	AND p.artist_id = #{artistId}


	AND p.label_id = #{labelId}


	AND p.album_id = #{albumId}


	AND p.country = #{country}


	AND p.pressing_year >= #{pressingYearFrom}


	AND p.pressing_year <= #{pressingYearTo}


	AND p.edition_type = #{editionType}


	AND EXISTS (
		SELECT 1 FROM product_genre pg
		WHERE pg.product_id = p.id
		AND pg.genre_id IN
		#{genreId}
	)


	AND p.price >= #{minPrice}


	AND p.price <= #{maxPrice}
